package org.local.donusturucu.qa;
import android.os.Bundle;import android.content.Context;import java.io.*;import java.lang.reflect.*;import java.util.*;import org.json.*;
public class ImageRelations extends RichChains {
 public void onStart(){Bundle result=new Bundle();try{Context c=getTargetContext();ClassLoader loader=c.getClassLoader();Class<?>type=Class.forName("org.local.donusturucu.RichDocument",true,loader),host=Class.forName("org.local.donusturucu.RichDocument$Host",true,loader);Method read=type.getDeclaredMethod("read",File.class,String.class,host);read.setAccessible(true);Object callback=Proxy.newProxyInstance(loader,new Class<?>[]{host},new InvocationHandler(){public Object invoke(Object p,Method m,Object[]args){return null;}});File root=new File(c.getExternalFilesDir(null),"image-relation-test");root.mkdirs();JSONArray rows=new JSONArray();
 for(int repeat=1;repeat<=3;repeat++)for(String name:new String[]{"rel-valid.docx","rel-missing-file.docx","rel-missing-rel.docx","rel-external-rel.docx","rel-traversal-rel.docx","rel-external.odt","rel-external.epub"}){JSONObject row=new JSONObject();row.put("case",name);row.put("repeat",repeat);try{File f=copy(name,root);String before=hash(f),ext=name.substring(name.lastIndexOf('.')+1);boolean rejected=false;Object doc=null;try{doc=read.invoke(null,f,ext,callback);}catch(InvocationTargetException e){if(!(e.getCause() instanceof IOException))throw e;rejected=true;row.put("rejection",e.getCause().toString());}
 if(name.equals("rel-valid.docx")){if(rejected)throw new IOException("Valid image rejected");Field field=type.getDeclaredField("blocks");field.setAccessible(true);int images=0;StringBuilder text=new StringBuilder();for(Object b:(List<?>)field.get(doc)){Field im=b.getClass().getDeclaredField("image"),tx=b.getClass().getDeclaredField("text");im.setAccessible(true);tx.setAccessible(true);if(im.get(b)!=null)images++;if(tx.get(b)!=null)text.append(tx.get(b));}if(images<1||!text.toString().contains("Merhaba"))throw new IOException("Valid image/text lost");row.put("images",images);}else if(!rejected)throw new IOException("Broken/external image silently accepted");
 if(!before.equals(hash(f)))throw new IOException("Original changed");row.put("source_unchanged",true);row.put("pass",true);
 }catch(Throwable e){row.put("pass",false);row.put("error",e.toString());}rows.put(row);JSONObject report=new JSONObject();report.put("cases",rows.length());int failures=0;for(int i=0;i<rows.length();i++)if(!rows.getJSONObject(i).getBoolean("pass"))failures++;report.put("failures",failures);report.put("rows",rows);Writer w=new OutputStreamWriter(new FileOutputStream(new File(root,"report.json")),"UTF-8");try{w.write(report.toString(2));}finally{w.close();}}
 result.putString("report",new File(root,"report.json").toString());finish(0,result);
 }catch(Throwable e){result.putString("error",e.toString());finish(1,result);}}
}
